<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
use Omnigo\{Database,Repository,SalesAnalytics,SalesCalendar,KoctasOrderMapper,KoctasProductMapper,HttpError};
function check(bool $ok,string $name): void { if (!$ok) throw new RuntimeException($name); }
function rejects(callable $fn,int $code): void { try{$fn();}catch(HttpError $e){check($e->getCode()===$code,'Hata kodu');return;}throw new RuntimeException('Hata bekleniyordu'); }
check(SalesCalendar::day('2026-09-30T21:00:00Z')==='2026-10-01','Türkiye ay sınırı');
$clock=new DateTimeImmutable('2026-10-09T00:01:00+03:00');
$snapshot=['channel'=>'Koçtaş','month'=>'2026-10','dailySales'=>['from'=>'2026-09-30T21:00:00Z','through'=>'2026-10-08T20:59:59Z','days'=>[]]];
check(!SalesCalendar::today([$snapshot],$clock)['channels'][0]['available'],'Düne kadar olan aktarım bugün sıfır değildir');
$snapshot['dailySales']['through']='2026-10-08T21:00:30Z';
$today=SalesCalendar::today([$snapshot],$clock)['channels'][0];check($today['available']&&$today['orders']===0&&$today['netCents']===0,'Doğrulanmış sıfır');
$snapshot['dailySales']['from']='2026-10-08T21:00:10Z';check(!SalesCalendar::today([$snapshot],$clock)['channels'][0]['available'],'Eksik gün sıfır değildir');
$line=['order_line_state'=>'SHIPPED','price'=>300,'quantity'=>3,'offer_sku'=>'A','product_title'=>'Örnek A','cancelations'=>[['amount'=>100,'quantity'=>1]],'refunds'=>[['amount'=>100,'quantity'=>1,'refund_state'=>'REFUNDED'],['amount'=>100,'quantity'=>1,'refund_state'=>'WAITING_REFUND']],'product_medias'=>[['mime_type'=>'image/jpeg','media_url'=>'https://images.example.test/product.jpg']]];
$product=KoctasProductMapper::map($line,30000,10000,10000);
check($product['netQuantity']===1&&$product['netCents']===10000,'İptal ve tamamlanmış iade adedi');
$missing=$line;unset($missing['cancelations'][0]['quantity']);check(KoctasProductMapper::map($missing,30000,10000,10000)['netQuantity']===null,'İade adedi tahmin edilmez');
foreach(['javascript:alert(1)','http://images.example.test/a.jpg','https://user:pass@images.example.test/a.jpg','https://127.0.0.1/a','https://printer.local/a','https://images.example.test:8443/a'] as $url)check(KoctasProductMapper::imageUrl($url)===null,'Geçersiz görsel');
$mediaPath='/media/product/image/1850c14a-43bd-4c35-9abf-de894575c6e0';
check(KoctasProductMapper::imageUrl($mediaPath)==='https://koctas.mirakl.net'.$mediaPath,'Koçtaş göreli görsel yolu');
check(KoctasProductMapper::imageUrl('//evil.example/image')===null&&KoctasProductMapper::imageUrl('/media/product/image/../../etc/passwd')===null,'Göreli yol sınırı');
check(KoctasProductMapper::mediaUrl([['type'=>'SMALL','mime_type'=>'JPG','media_url'=>'https://images.example.test/small.jpg'],['type'=>'LARGE','mime_type'=>'JPG','media_url'=>$mediaPath]])==='https://koctas.mirakl.net'.$mediaPath,'Büyük görsel seçilir');
$db=new Database(['dsn'=>'sqlite::memory:']);$db->pdo->exec(file_get_contents(__DIR__.'/schema.sqlite.sql'));
$repo=new Repository($db);$company=$repo->createCompany('Birinci');$other=$repo->createCompany('İkinci');$client=['role'=>'client'];$admin=['role'=>'admin'];
$save=function(int $company,string $kind,array $value)use($db):void{$db->run('INSERT INTO records(company_id,kind,payload,updated) VALUES(?,?,?,?)',[$company,$kind,json_encode($value),gmdate('c')]);};
$state=['startDate'=>'2026-09-30T21:00:00Z','watermark'=>'2026-10-08T22:00:00Z','detailsVersion'=>1];$save($company,'sync_koctas',$state);
$make=function(string $id,string $at,array $line):array{return KoctasOrderMapper::map(['order_id'=>$id,'currency_iso_code'=>'TRY','created_date'=>$at,'order_state'=>'SHIPPED','order_lines'=>[$line],'customer'=>['name'=>'Gizli alıcı']]);};
$first=$make('one','2026-09-30T21:00:00Z',$line);$save($company,'order_koctas',$first);
$second=$line;$second['quantity']=5;$second['offer_sku']='B';$second['product_title']='Örnek B';$second['cancelations']=[];$second['refunds']=[];$second['price']=250;
$save($company,'order_koctas',$make('two','2026-10-01T20:59:59Z',$second));
$save($company,'order_koctas',$make('next','2026-10-01T21:00:00Z',$second));
$save($other,'order_koctas',$make('foreign','2026-10-01T10:00:00Z',$second));
$service=new SalesAnalytics($db);$result=$service->report($client,$company,'Koçtaş','2026-10-01','2026-10-01');
check($result['totals']['orders']===2&&$result['totals']['grossCents']===55000&&$result['totals']['netCents']===35000,'Dahil tarih sınırları, satır tutarı adede çarpılmaz, firma yalıtımı');
check(array_column($result['topProducts'],'netQuantity')===[5,2]&&$result['topProducts'][0]['sku']==='B','Müşteri TOP 10 iptal sonrası adedi, iadeyi ikinci kez düşmez.');
$adminResult=$service->report($admin,$company,'Koçtaş','2026-10-01','2026-10-01');
check(array_column($adminResult['topProducts'],'netQuantity')===[5,1],'Yönetici TOP 10 net adet sıralaması');
$customerReport=\Omnigo\CustomerTurnoverDisplay::project($result);
check($customerReport['totals']['turnoverCents']===45000&&$customerReport['totals']['soldUnits']===7,'Müşteri toplam cirosu ve adedi satış eksi iptal olmalı.');
check(!str_contains(json_encode($result),'Gizli alıcı'),'Kişisel veri yayılmaz');
$result=$service->report($client,$company,'Koçtaş','2026-10-01','2026-10-02');check($result['topProducts'][0]['netQuantity']===10&&$result['productCount']===2,'Ürünler birleştirilir');
check(!$service->report($client,$company,'n11','2026-10-01','2026-10-01')['available'],'Bağlantısız panel sıfır değildir');
check(!$service->report($client,$other,'Koçtaş','2026-10-01','2026-10-01')['available'],'Başka firmanın aktarımı kullanılmaz');
rejects(fn()=>$service->report($client,$company,'Koçtaş','2026-10-02','2026-10-01'),400);
rejects(fn()=>$service->report($client,$company,'Koçtaş','2024-01-01','2026-10-01'),400);
rejects(fn()=>$service->report($client,$company,'Yok','2026-10-01','2026-10-01'),404);
$channel=array_values(array_filter($repo->records($company,'channels',$admin),fn($r)=>$r['name']==='Koçtaş'))[0];
$inactive=['name'=>'Koçtaş','status'=>'inactive','storeName'=>'','connection'=>'not_connected'];$db->run('UPDATE records SET payload=? WHERE id=?',[json_encode($inactive),$channel['id']]);
rejects(fn()=>$service->report($client,$company,'Koçtaş','2026-10-01','2026-10-01'),404);
check($service->report($admin,$company,'Koçtaş','2026-10-01','2026-10-01')['available'],'Yönetici pasif mağaza geçmişi');
for($i=1;$i<=26;$i++){$item=$second;$item['offer_sku']='sku-'.$i;$item['quantity']=$i;$save($company,'order_koctas',$make('page-'.$i,'2026-10-03T10:00:00Z',$item));}
$pageOne=$service->report($admin,$company,'Koçtaş','2026-10-03','2026-10-03');$pageTwo=$service->report($admin,$company,'Koçtaş','2026-10-03','2026-10-03',1);
check(count($pageOne['products'])===25&&$pageOne['hasMore']&&count($pageTwo['products'])===1&&!$pageTwo['hasMore'],'Ürün sayfalama');
check(count($pageOne['topProducts'])===10&&array_column($pageOne['topProducts'],'netQuantity')===range(26,17),'İlk on satış adedine göre sıralanır');
check($pageOne['totals']===$pageTwo['totals']&&$pageOne['topProducts']===$pageTwo['topProducts'],'Sayfalama toplamları ve TOP 10 sırasını değiştirmez');
$legacy=$first;unset($legacy['products']);$legacy['externalId']='legacy';$save($company,'order_koctas',$legacy);
$result=$service->report($admin,$company,'Koçtaş','2026-10-01','2026-10-01');check($result['missingProductOrders']===1&&$result['topProducts']===[],'Eksik ürün aktarımı yanlış sıralama yayımlamaz');
$result=$service->report($admin,$company,'Koçtaş','2026-09-01','2026-10-01');check($result['partialHistory'],'Geçmiş kapsamı açıkça bildirilir');
$state['scanEnd']=$state['watermark'];$db->run("UPDATE records SET payload=? WHERE company_id=? AND kind='sync_koctas'",[json_encode($state),$company]);
check(!$service->report($admin,$company,'Koçtaş','2026-10-01','2026-10-01')['available'],'Yarım aktarım raporlanmaz');
echo "Satış analizi: tarih sınırları, tutarlar, adetler, firma yalıtımı, eksik veri ve TOP 10 geçti.\n";
